var _markdown = "\n\n# Custom Footer [#custom-footer]\n\nThe Onboarding component allows you to create custom footers for enhanced customization.\n\n## Basic Custom Footer [#basic-custom-footer]\n\n```jsx\nconst CustomFooter = ({ nextPage, currentPage, numberOfScreens }) => (\n  <View style={styles.footer}>\n    <View style={styles.pagination}>\n      {Array.from({ length: numberOfScreens }).map((_, index) => (\n        <View\n          key={index}\n          style={[\n            styles.dot,\n            currentPage === index && styles.activeDot\n          ]}\n        />\n      ))}\n    </View>\n    <TouchableOpacity\n      style={styles.button}\n      onPress={nextPage}\n    >\n      <Text style={styles.buttonText}>\n        {currentPage === numberOfScreens - 1 ? 'Done' : 'Next'}\n      </Text>\n    </TouchableOpacity>\n  </View>\n);\n\nconst App = () => (\n  <Onboarding\n    pages={[/* your pages */]}\n    customFooter={CustomFooter}\n  />\n);\n```\n\n## Animated Footer [#animated-footer]\n\n```jsx\nconst AnimatedFooter = ({ nextPage, currentPage, numberOfScreens }) => {\n  const progress = useRef(new Animated.Value(0)).current;\n\n  useEffect(() => {\n    Animated.timing(progress, {\n      toValue: currentPage / (numberOfScreens - 1),\n      duration: 300,\n      useNativeDriver: false,\n    }).start();\n  }, [currentPage]);\n\n  return (\n    <View style={styles.footer}>\n      <Animated.View \n        style={[\n          styles.progressBar,\n          {\n            width: progress.interpolate({\n              inputRange: [0, 1],\n              outputRange: ['0%', '100%'],\n            }),\n          },\n        ]}\n      />\n      <TouchableOpacity onPress={nextPage}>\n        <Text>Continue</Text>\n      </TouchableOpacity>\n    </View>\n  );\n};\n```\n\n## Footer with Skip [#footer-with-skip]\n\n```jsx\nconst FooterWithSkip = ({ nextPage, currentPage, numberOfScreens }) => {\n  const navigation = useNavigation();\n\n  return (\n    <View style={styles.footer}>\n      <TouchableOpacity\n        onPress={() => navigation.replace('Home')}\n      >\n        <Text>Skip</Text>\n      </TouchableOpacity>\n      \n      <View style={styles.dots}>\n        {Array.from({ length: numberOfScreens }).map((_, i) => (\n          <View\n            key={i}\n            style={[\n              styles.dot,\n              i === currentPage && styles.activeDot\n            ]}\n          />\n        ))}\n      </View>\n      \n      <TouchableOpacity onPress={nextPage}>\n        <Text>\n          {currentPage === numberOfScreens - 1 ? 'Start' : 'Next'}\n        </Text>\n      </TouchableOpacity>\n    </View>\n  );\n};\n```\n\n## Styling Examples [#styling-examples]\n\n```jsx\nconst styles = StyleSheet.create({\n  footer: {\n    padding: 20,\n    flexDirection: 'row',\n    justifyContent: 'space-between',\n    alignItems: 'center',\n  },\n  pagination: {\n    flexDirection: 'row',\n    justifyContent: 'center',\n  },\n  dot: {\n    width: 8,\n    height: 8,\n    borderRadius: 4,\n    backgroundColor: '#ccc',\n    marginHorizontal: 4,\n  },\n  activeDot: {\n    backgroundColor: '#007AFF',\n    width: 16,\n  },\n  button: {\n    backgroundColor: '#007AFF',\n    paddingHorizontal: 20,\n    paddingVertical: 10,\n    borderRadius: 8,\n  },\n  buttonText: {\n    color: '#fff',\n    fontWeight: 'bold',\n  },\n  progressBar: {\n    height: 3,\n    backgroundColor: '#007AFF',\n    position: 'absolute',\n    top: 0,\n    left: 0,\n  },\n});\n```\n\n## Live Example [#live-example]\n\nTry this example on [Expo Snack](https://snack.expo.dev/@lekgwaraj/react-native-app-onboard-custom-pagination?platform=ios)\n";
